import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.76ZGnlPi.js";const k=JSON.parse('{"title":"Office Locations - Admin Management","description":"","frontmatter":{},"headers":[],"relativePath":"admin/office-locations/index.md","filePath":"admin/office-locations/index.md"}'),o={name:"admin/office-locations/index.md"};function d(n,e,l,r,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="office-locations-admin-management" tabindex="-1">Office Locations - Admin Management <a class="header-anchor" href="#office-locations-admin-management" aria-label="Permalink to &quot;Office Locations - Admin Management&quot;">​</a></h1><p>Admin-only guide for managing the physical Ahlaan offices used by the <strong>IN_PERSON</strong> payment rail: the offices a customer can walk into and settle a custom-booking invoice in cash.</p><p>All endpoints require:</p><ul><li><code>Authorization: Bearer &lt;jwt&gt;</code> with a user that has the <code>ADMIN</code> role.</li><li>Base path: <code>/api/v1/admin/office-locations</code></li></ul><hr><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>The IN_PERSON rail needs a destination the customer can be sent to, exactly the way the manual bank transfer rail needs a destination bank account. This module is the office equivalent of <a href="./../manual-transfer/">Manual Transfer bank accounts</a>.</p><table tabindex="0"><thead><tr><th>Rail</th><th>Destination registry</th><th>Selected by</th></tr></thead><tbody><tr><td>Manual bank transfer</td><td><code>ManualTransferBankAccount</code></td><td>Customer picks, or auto-picked by priority</td></tr><tr><td><strong>In-person office</strong></td><td><strong><code>OfficeLocation</code></strong></td><td><strong>Always auto-picked by priority. There is no customer picker.</strong></td></tr></tbody></table><blockquote><p><strong>Selection is server-side only.</strong> The customer never chooses an office and the API accepts no office id from the client. The IN_PERSON rail always picks the <strong>highest-priority active office for the currency</strong>, ordered <code>priority</code> descending then <code>createdAt</code> ascending. <code>priority</code> is therefore the operational lever that decides where customers are sent.</p></blockquote><hr><h2 id="field-reference" tabindex="-1">Field reference <a class="header-anchor" href="#field-reference" aria-label="Permalink to &quot;Field reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>code</code></td><td>string</td><td>yes</td><td>Unique, uppercased on write. Letters, digits and hyphens only, 2-32 chars. Example <code>JED-HQ</code>.</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Shown to the customer. 2-160 chars.</td></tr><tr><td><code>addressLine</code></td><td>string</td><td>yes</td><td>Shown to the customer. 4-400 chars.</td></tr><tr><td><code>city</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>country</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>postalCode</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>phone</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>openingHours</code></td><td>string</td><td>no</td><td>Free text, e.g. <code>Sun-Thu 09:00-17:00</code>. Not parsed or enforced.</td></tr><tr><td><code>mapUrl</code></td><td>string</td><td>no</td><td>Must be a valid <code>http</code>/<code>https</code> URL.</td></tr><tr><td><code>currency</code></td><td>string</td><td>no</td><td>Defaults to <code>SAR</code>. The IN_PERSON rail is SAR only, so a non-SAR office is never auto-picked by it.</td></tr><tr><td><code>isActive</code></td><td>boolean</td><td>no</td><td>Defaults to <code>true</code>. Inactive offices are excluded from the auto-pick.</td></tr><tr><td><code>priority</code></td><td>integer</td><td>no</td><td>Defaults to <code>100</code>. Range 0-1000. <strong>Higher = preferred.</strong></td></tr><tr><td><code>notes</code></td><td>string</td><td>no</td><td>Surfaced to the customer alongside the address.</td></tr></tbody></table><p>Server-managed: <code>id</code>, <code>deletedAt</code>, <code>createdBy</code>, <code>updatedBy</code>, <code>createdAt</code>, <code>updatedAt</code>.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="create" tabindex="-1">Create <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JED-HQ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ahlaan Jeddah Office&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;addressLine&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;King Abdulaziz Road 12, Al Balad&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jeddah&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;country&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Saudi Arabia&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;phone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+966 12 345 6789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;openingHours&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Sun-Thu 09:00-17:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mapUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://maps.google.com/?q=21.4858,39.1925&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;priority&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>201</code> on success, returning the created row.</li><li><code>400</code> when validation fails.</li><li><code>409</code> when <code>code</code> is already taken: <code>&quot;An office location with code &#39;JED-HQ&#39; already exists.&quot;</code></li></ul><h3 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations?currency=SAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;isActive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre></div><ul><li>Both query parameters are optional.</li><li>The admin list <strong>includes soft-deleted rows</strong> so history stays visible. Filter them out client-side on <code>deletedAt</code>.</li><li>Ordered <code>priority</code> descending, then <code>createdAt</code> ascending. This is the same order the IN_PERSON auto-pick uses, so <strong>the first active SAR row in this list is the office customers will be sent to.</strong></li></ul><h3 id="get-one" tabindex="-1">Get one <a class="header-anchor" href="#get-one" aria-label="Permalink to &quot;Get one&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations/:id</span></span></code></pre></div><p><code>404</code> when the office does not exist.</p><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations/:id</span></span></code></pre></div><p>Partial update: only the fields you send are written. <code>code</code> and <code>currency</code> are uppercased.</p><ul><li><code>404</code> when the office does not exist.</li><li><code>409</code> when the new <code>code</code> collides with another office.</li></ul><h3 id="toggle-active" tabindex="-1">Toggle active <a class="header-anchor" href="#toggle-active" aria-label="Permalink to &quot;Toggle active&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations/:id/toggle-active</span></span></code></pre></div><p>Flips <code>isActive</code>. Deactivating removes the office from the auto-pick immediately. <strong>Payments already issued against it keep pointing at it</strong>, so a customer already on their way to that office still sees the correct address.</p><h3 id="delete-soft" tabindex="-1">Delete (soft) <a class="header-anchor" href="#delete-soft" aria-label="Permalink to &quot;Delete (soft)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/office-locations/:id</span></span></code></pre></div><ul><li><strong>Always a soft delete.</strong> Sets <code>isActive=false</code> and stamps <code>deletedAt</code>. There is no hard delete on this resource.</li><li>Rationale: a settled payment freezes the office it was issued against. Hard-deleting the row would orphan that payment history.</li><li><code>409</code> when the office is already deleted.</li></ul><blockquote><p>This differs deliberately from the manual-transfer bank accounts endpoint, which hard-deletes an account that no proof references. Offices are never hard-deleted regardless of reference count.</p></blockquote><hr><h2 id="switching-offices" tabindex="-1">Switching offices <a class="header-anchor" href="#switching-offices" aria-label="Permalink to &quot;Switching offices&quot;">​</a></h2><p>To move customers from one office to another:</p><ol><li>Create the new office with a <strong>higher <code>priority</code></strong> than the current one.</li><li>Deactivate the old office (<code>toggle-active</code>) once you are ready.</li></ol><p>Do not delete the old office. Payments already issued against it must stay readable.</p><hr><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h2><p>All write routes (<code>POST</code>, <code>PATCH</code>, <code>DELETE</code>) are throttled to <strong>20 requests per 60 seconds</strong>. Reads are not separately throttled beyond the global default.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../manual-transfer/">Manual Transfer Management</a> - the sibling destination registry, and the <code>POST /admin/invoice/:id/office-settlement</code> endpoint that settles an in-person payment.</li><li><a href="./../invoice/">Invoice Management</a> - where the settled office payment and its proof are surfaced.</li></ul>`,47)])])}const u=t(o,[["render",d]]);export{k as __pageData,u as default};
